def diag_period_classes(grid):
    """Smallest period P and direction such that each wrapped diagonal class ((c-r) or (r+c)) mod P has one consistent nonzero color; returns (P, sign, {class: color})."""
    n = len(grid)
    for sign in (1, -1):
        for P in range(2, n + 1):
            col, ok = {}, True
            for r in range(n):
                for c in range(n):
                    v = grid[r][c]
                    if v:
                        k = (c - sign * r) % P
                        if k in col and col[k] != v:
                            ok = False
                            break
                        col[k] = v
                if not ok:
                    break
            if ok:
                return P, sign, col
    return n, 1, {}

def fill_diag_period(grid):
    """Complete a partially drawn periodic diagonal-stripe pattern: every cell takes the color of its wrapped diagonal class; classes with no observed color stay 0."""
    P, sign, col = diag_period_classes(grid)
    n = len(grid)
    return [[col.get((c - sign * r) % P, 0) for c in range(n)] for r in range(n)]

